from AlgorithmImports import *
from collections import deque
import math


class ExactStrategyAlgorithm(QCAlgorithm):
    RSI_THRESHOLD = 70.0

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.required_symbols = (
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig,
        )

        self.SetWarmUp(100, Resolution.Daily)

        self.spy_closes = deque(maxlen=101)

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.rsi_period = 14
        self.rsi_delta_count = 0
        self.rsi_gain_sum = 0.0
        self.rsi_loss_sum = 0.0
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.lots = {
            "A": 0,
            "B": 0,
        }

        self.pending_orders = {
            "A": False,
            "B": False,
        }

    def OnData(self, data):
        bars = data.Bars

        if self.spy in bars:
            self.spy_closes.append(float(bars[self.spy].Close))

        if self.aapl in bars:
            self._update_aapl_state(float(bars[self.aapl].Close))

        if self.IsWarmingUp:
            return

        if not all(symbol in bars for symbol in self.required_symbols):
            return

        spy_close = float(bars[self.spy].Close)
        aapl_close = float(bars[self.aapl].Close)

        spy_crosses_below = self._spy_crosses_below_sma()
        spy_crosses_above = self._spy_crosses_above_sma()

        aapl_sell_signal = (
            self.aapl_rsi is not None
            and self.aapl_rsi > self.RSI_THRESHOLD
        )
        aapl_buy_signal = self.aapl_red_streak >= 3

        # Evaluate sells before buys.
        if (
            self.lots["A"] > 0
            and not self.pending_orders["A"]
            and spy_crosses_below
        ):
            self._submit_order(
                "A",
                self.spy,
                -self.lots["A"],
                "A_SELL",
            )

        if (
            self.lots["B"] > 0
            and not self.pending_orders["B"]
            and aapl_sell_signal
        ):
            self._submit_order(
                "B",
                self.aapl,
                -self.lots["B"],
                "B_SELL",
            )

        if (
            self.lots["A"] == 0
            and not self.pending_orders["A"]
            and spy_crosses_above
            and spy_close > 0
        ):
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = int(math.floor(target_value / spy_close))

            if quantity > 0:
                self._submit_order(
                    "A",
                    self.spy,
                    quantity,
                    "A_BUY",
                )

        if (
            self.lots["B"] == 0
            and not self.pending_orders["B"]
            and aapl_buy_signal
            and float(self.Portfolio.Cash) >= 20000.0
            and aapl_close > 0
        ):
            quantity = int(math.floor(20000.0 / aapl_close))

            if quantity > 0:
                self._submit_order(
                    "B",
                    self.aapl,
                    quantity,
                    "B_BUY",
                )

    def _update_aapl_state(self, close):
        if self.aapl_previous_close is None:
            self.aapl_previous_close = close
            return

        change = close - self.aapl_previous_close

        if change < 0:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        self.rsi_delta_count += 1

        if self.rsi_delta_count <= self.rsi_period:
            self.rsi_gain_sum += gain
            self.rsi_loss_sum += loss

            if self.rsi_delta_count == self.rsi_period:
                self.rsi_average_gain = (
                    self.rsi_gain_sum / self.rsi_period
                )
                self.rsi_average_loss = (
                    self.rsi_loss_sum / self.rsi_period
                )
                self.aapl_rsi = self._calculate_rsi()
        else:
            self.rsi_average_gain = (
                (self.rsi_average_gain * (self.rsi_period - 1)) + gain
            ) / self.rsi_period

            self.rsi_average_loss = (
                (self.rsi_average_loss * (self.rsi_period - 1)) + loss
            ) / self.rsi_period

            self.aapl_rsi = self._calculate_rsi()

        self.aapl_previous_close = close

    def _calculate_rsi(self):
        if self.rsi_average_loss == 0:
            return 100.0

        relative_strength = (
            self.rsi_average_gain / self.rsi_average_loss
        )
        return 100.0 - (100.0 / (1.0 + relative_strength))

    def _spy_crosses_above_sma(self):
        if len(self.spy_closes) < 101:
            return False

        closes = list(self.spy_closes)
        yesterday_sma = sum(closes[-101:-1]) / 100.0
        today_sma = sum(closes[-100:]) / 100.0

        return (
            closes[-2] <= yesterday_sma
            and closes[-1] > today_sma
        )

    def _spy_crosses_below_sma(self):
        if len(self.spy_closes) < 101:
            return False

        closes = list(self.spy_closes)
        yesterday_sma = sum(closes[-101:-1]) / 100.0
        today_sma = sum(closes[-100:]) / 100.0

        return (
            closes[-2] >= yesterday_sma
            and closes[-1] < today_sma
        )

    def _submit_order(self, slot, symbol, quantity, tag):
        if quantity == 0 or self.pending_orders[slot]:
            return

        self.pending_orders[slot] = True
        ticket = self.MarketOrder(symbol, quantity, tag=tag)

        if ticket is None:
            self.pending_orders[slot] = False

    def OnOrderEvent(self, order_event):
        order = self.Transactions.GetOrderById(order_event.OrderId)

        if order is None:
            return

        if order.Tag == "A_BUY" or order.Tag == "A_SELL":
            slot = "A"
        elif order.Tag == "B_BUY" or order.Tag == "B_SELL":
            slot = "B"
        else:
            return

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.PartiallyFilled,
        ):
            self.lots[slot] += int(order_event.FillQuantity)
            self.lots[slot] = max(0, self.lots[slot])

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            self.pending_orders[slot] = False
